// UserPosts is the resolver for the userPosts field.
func (r *queryResolver) UserPosts(ctx context.Context, username string, first int, after *string) (*model.PostConnection, error) {
	fmt.Printf("[Gateway] UserPosts query received for username: %s, first: %d\n", username, first)

	// 通过用户服务获取用户ID
	fmt.Printf("[Gateway] UserPosts calling user-service GetUserByUsername\n")
	userRes, err := r.UserServiceClient.GetUserByUsername(ctx, &user_proto.GetUserByUsernameRequest{
		Username: username,
	})
	if err != nil {
		fmt.Printf("[Gateway] UserPosts user-service call failed: %v\n", err)
		return nil, fmt.Errorf("failed to get user by username: %w", err)
	}
	if userRes.Error != nil {
		fmt.Printf("[Gateway] UserPosts user-service returned error: %s\n", userRes.Error.Message)
		return nil, errors.New(userRes.Error.Message)
	}
	if userRes.User == nil {
		fmt.Printf("[Gateway] UserPosts user not found: %s\n", username)
		return nil, fmt.Errorf("user not found: %s", username)
	}

	fmt.Printf("[Gateway] UserPosts found user ID: %s for username: %s\n", userRes.User.Id, username)

	// 获取当前请求用户ID
	claims := middleware.GetUserClaims(ctx)
	requestingUserId := ""
	if claims != nil {
		requestingUserId = claims.UserID
	}

	// 处理分页游标
	cursor := ""
	if after != nil {
		cursor = *after
	}

	// 使用真实的用户ID获取帖子
	fmt.Printf("[Gateway] UserPosts calling content-service GetUserPosts for user: %s, requesting user: %s, cursor: %s\n", userRes.User.Id, requestingUserId, cursor)
	res, err := r.ContentServiceClient.GetUserPosts(ctx, &content_proto.GetUserPostsRequest{
		UserId:           userRes.User.Id,
		RequestingUserId: requestingUserId,
		Limit:            int32(first),
		Cursor:           cursor,
	})
	if err != nil {
		fmt.Printf("[Gateway] UserPosts content-service call failed: %v\n", err)
		return nil, fmt.Errorf("failed to get user posts: %w", err)
	}
	if res.Error != nil {
		fmt.Printf("[Gateway] UserPosts content-service returned error: %s\n", res.Error.Message)
		return nil, errors.New(res.Error.Message)
	}

	fmt.Printf("[Gateway] UserPosts got %d posts from content-service\n", len(res.Posts))

	// 转换为GraphQL连接类型
	edges := make([]model.PostEdge, len(res.Posts))
	for i, post := range res.Posts {
		fmt.Printf("[Gateway] UserPosts converting post %d: ID=%s, Content=%s\n", i, post.Id, post.Content[:min(50, len(post.Content))])
		edges[i] = model.PostEdge{
			Node:   r.postProtoToGql(post),
			Cursor: post.Id, // 简化处理，使用ID作为cursor
		}
	}

	fmt.Printf("[Gateway] UserPosts returning %d edges\n", len(edges))

	// 计算 endCursor
	var endCursor *string
	if len(edges) > 0 && res.HasMore {
		lastCursor := edges[len(edges)-1].Cursor
		endCursor = &lastCursor
		fmt.Printf("[Gateway] UserPosts setting endCursor: %s\n", lastCursor)
	}

	return &model.PostConnection{
		Edges: edges,
		PageInfo: &model.PageInfo{
			HasNextPage: res.HasMore,
			EndCursor:   endCursor,
		},
	}, nil
}

